/// An operation's error channel: either the synthetic scaffold signal, or one of the
/// operation's own modeled errors.
#[derive(Debug)]
pub enum Scaffolded<E> {
    /// The operation is generated but has no implementation. Renders as HTTP 501.
    NotImplemented(NotImplemented),
    /// A modeled error the operation declares. Renders with the model's own status.
    Modeled(E),
    /// The request was refused as invalid. Renders as HTTP 400 with the error code
    /// `ValidationException`.
    ///
    /// On the JSON and CBOR protocols that is the same status and code the boundary
    /// validator answers with. Two differences are worth knowing, and neither is
    /// specific to this variant — every handler-returned error shares them:
    /// the awsJson families omit the `x-amzn-errortype` header that the boundary
    /// path sets, and the query protocols render a boundary refusal as
    /// `MalformedQueryString` rather than `ValidationException`, so a client
    /// matching on the error code there sees two codes for one logical failure.
    ValidationException(ValidationException),
    /// The request was refused as invalid, with HTTP 400 and the error code
    /// `ValidationError` — the code THIS service answers an unsatisfiable request
    /// with, and the one its clients branch on. The payload is the same single
    /// `message` member; only the wire code differs from
    /// [`Scaffolded::ValidationException`].
    ValidationError(ValidationException),
    /// The operation is not available to this account at all, with HTTP 400 and
    /// the error code `UnsupportedOperation`. Not a bad request and not an
    /// unwritten one: the service itself refuses every call, whatever the request
    /// carries. The payload is the same single `message` member as the refusals
    /// above.
    UnsupportedOperation(ValidationException),
    /// The request was refused with HTTP 400 and the error code `InvalidQueryParameter` —
    /// the code this service answers a request whose members are each well-formed but whose
    /// launch source cannot serve the group it would configure. The payload is the same
    /// single `message` member as the refusals above; only the wire code differs.
    InvalidQueryParameter(ValidationException),
    /// The caller may not perform the action the request named, with HTTP 403 and the error
    /// code `AccessDenied`. Not a bad request: the request is one the service would serve
    /// for a caller the IAM policies in force permit. The payload is the same single
    /// `message` member as the refusals above.
    AccessDenied(ValidationException),
}

impl<E> Scaffolded<E> {
    /// The scaffold signal for `operation`.
    pub fn not_implemented(operation: &str) -> Self {
        Self::NotImplemented(NotImplemented::new(operation))
    }

    /// Refuse the request as invalid, with HTTP 400 `ValidationException`.
    ///
    /// Reach for this when the request is wrong in a way the model cannot express,
    /// so the boundary validator passed it: a value outside a rule the service
    /// enforces but does not model, or a combination of members that cannot hold
    /// together. Answer it INSTEAD of `not_implemented` — a 501 says "nobody has
    /// written this yet", which is a different claim and is counted as one.
    ///
    /// If this service's model declares its own `ValidationException` (or another
    /// client-input error) use THAT: the modeled shape may carry members beyond
    /// `message` — a `reason`, a field list — and a real client reads them. When the
    /// operation already lists it, it is a plain variant on the generated error enum;
    /// `#[operation_error]`'s `extra_errors` is only for widening in a shape the
    /// SERVICE models that this OPERATION does not list.
    pub fn validation(message: impl Into<String>) -> Self {
        Self::ValidationException(ValidationException::new(message))
    }

    /// Refuse the request as invalid with HTTP 400 `ValidationError`.
    ///
    /// This is the refusal Amazon EC2 Auto Scaling itself answers with — an
    /// unknown Auto Scaling group or launch configuration name, a group size or
    /// desired capacity outside the bounds the group was created with, a request
    /// naming neither a launch template nor a launch configuration. The model
    /// declares no client-input error for any of it, so the code lives here rather
    /// than on an operation's error enum; say what was wrong and name the member,
    /// because the caller has to fix the request from this text alone.
    pub fn validation_error(message: impl Into<String>) -> Self {
        Self::ValidationError(ValidationException::new(message))
    }

    /// Refuse the request with HTTP 400 `InvalidQueryParameter`.
    ///
    /// For a request whose arguments are each acceptable on their own but whose combination
    /// with the state a referenced resource carries is not — the launch template a
    /// non-mixed-instances group would launch from naming no instance type. Say what the
    /// referenced resource has to carry, because the caller has to change that resource or
    /// the shape of the group, not the spelling of this argument.
    pub fn invalid_query_parameter(message: impl Into<String>) -> Self {
        Self::InvalidQueryParameter(ValidationException::new(message))
    }

    /// Refuse the operation outright with HTTP 400 `UnsupportedOperation`.
    ///
    /// For an operation Amazon EC2 Auto Scaling still models but no longer serves
    /// to this account, so no request can succeed and nothing is stored. Say what
    /// is unavailable and what to use instead, because the caller has to change
    /// which operation it calls — not which values it sends.
    pub fn unsupported_operation(message: impl Into<String>) -> Self {
        Self::UnsupportedOperation(ValidationException::new(message))
    }

    /// Refuse the request with HTTP 403 `AccessDenied`.
    ///
    /// For a request the IAM policies in force on the principal it speaks for do not permit:
    /// say who was refused, which action and on which resource, because that is what the
    /// caller has to have granted. The decision itself belongs to
    /// [`crate::service::authorization`], which words the sentence.
    pub fn access_denied(message: impl Into<String>) -> Self {
        Self::AccessDenied(ValidationException::new(message))
    }
}

impl<E: std::fmt::Display> std::fmt::Display for Scaffolded<E> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::NotImplemented(e) => write!(f, "{e}"),
            Self::Modeled(e) => write!(f, "{e}"),
            Self::ValidationException(e) => write!(f, "{e}"),
            Self::ValidationError(e) => write!(f, "{e}"),
            Self::UnsupportedOperation(e) => write!(f, "{e}"),
            Self::InvalidQueryParameter(e) => write!(f, "{e}"),
            Self::AccessDenied(e) => write!(f, "{e}"),
        }
    }
}

/// `source()` forwards to the modeled error rather than taking the default `None`, so a
/// modeled error's own `source()` is preserved through the wrapper.
impl<E: std::error::Error + 'static> std::error::Error for Scaffolded<E> {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::NotImplemented(e) => e.source(),
            Self::Modeled(e) => e.source(),
            Self::ValidationException(e) => e.source(),
            Self::ValidationError(e) => e.source(),
            Self::UnsupportedOperation(e) => e.source(),
            Self::InvalidQueryParameter(e) => e.source(),
            Self::AccessDenied(e) => e.source(),
        }
    }
}

/// Every `OperationError` method delegates to the modeled error, so wrapping an
/// implemented operation's error channel changes NOTHING about how that error is
/// rendered. Only the synthetic variant behaves differently — and it is the one that
/// must answer 501.
impl<E: OperationError> OperationError for Scaffolded<E> {
    fn as_serializable(&self) -> &dyn SerializableStruct {
        match self {
            Self::NotImplemented(e) => e,
            Self::Modeled(e) => e.as_serializable(),
            Self::ValidationException(e) => e,
            Self::ValidationError(e) => e,
            Self::UnsupportedOperation(e) => e,
            Self::InvalidQueryParameter(e) => e,
            Self::AccessDenied(e) => e,
        }
    }

    fn variant_schema(&self) -> &'static Schema {
        match self {
            Self::NotImplemented(_) => &NOT_IMPLEMENTED_SCHEMA,
            Self::Modeled(e) => e.variant_schema(),
            Self::ValidationException(_) => &VALIDATION_EXCEPTION_SCHEMA,
            Self::ValidationError(_) => &VALIDATION_ERROR_SCHEMA,
            Self::UnsupportedOperation(_) => &UNSUPPORTED_OPERATION_SCHEMA,
            Self::InvalidQueryParameter(_) => &INVALID_QUERY_PARAMETER_SCHEMA,
            Self::AccessDenied(_) => &ACCESS_DENIED_SCHEMA,
        }
    }

    /// The wire error code (`__type` on JSON/CBOR, `<Code>` on XML).
    ///
    /// Keep the literal as it is: changing it changes the wire error code clients match
    /// on. It is intentionally not tied to the Rust variant name.
    fn shape_name(&self) -> &'static str {
        match self {
            Self::NotImplemented(_) => "NotImplemented",
            Self::Modeled(e) => e.shape_name(),
            Self::ValidationException(_) => "ValidationException",
            Self::ValidationError(_) => "ValidationError",
            Self::UnsupportedOperation(_) => "UnsupportedOperation",
            Self::InvalidQueryParameter(_) => "InvalidQueryParameter",
            Self::AccessDenied(_) => "AccessDenied",
        }
    }

    /// 501 for the scaffold signal.
    ///
    /// Keep it 501 and not a 5xx server fault: SDK retry classifiers treat those as
    /// retryable, so a client would retry an operation that can never succeed.
    fn http_status(&self) -> u16 {
        match self {
            Self::NotImplemented(_) => 501,
            Self::Modeled(e) => e.http_status(),
            Self::ValidationException(_) => 400,
            Self::ValidationError(_) => 400,
            Self::UnsupportedOperation(_) => 400,
            Self::InvalidQueryParameter(_) => 400,
            Self::AccessDenied(_) => 403,
        }
    }

    fn query_error_code(&self) -> Option<&'static str> {
        match self {
            // No awsQuery code: the synthetic shape is not in the model, so there is
            // no `awsQueryError` trait to honour. The 501 + `<Code>NotImplemented`
            // envelope carries the signal on the query protocols too.
            Self::NotImplemented(_) => None,
            Self::Modeled(e) => e.query_error_code(),
            // Same reason: the synthetic shape carries no `awsQueryError` trait.
            // Both refusals render their `<Code>` from `shape_name` instead, which
            // on the query protocols is exactly the code the service answers with.
            Self::ValidationException(_) => None,
            Self::ValidationError(_) => None,
            Self::UnsupportedOperation(_) => None,
            Self::InvalidQueryParameter(_) => None,
            // Same reason again: the synthetic shape carries no `awsQueryError` trait, so the
            // `<Code>AccessDenied</Code>` comes from `shape_name`.
            Self::AccessDenied(_) => None,
        }
    }
}
